TWComponent.script:
/**-------------------------- Add SQL Parameters --------------------------**/
function addSQLParameter(value){
	if(value == null && typeof value == "string"){
		value= ""; 
	}
	else if(value == null && typeof value == "number"){
		value= 0;
	}
	else if(value == null && typeof value == "boolean"){
		value = "0";
	}
 var parameter = new tw.object.SQLParameter();  
   parameter.value = value;
   parameter.mode = "IN";
return parameter;
}
tw.local.sql = "INSERT INTO "+ tw.env.LKP_DB_Schema + ".ODC_LOGHISTORY"+
               "(STARTTIME, ENDTIME, USERNAME, ROLE, STEPNAME, ACTION, RETURNREASON, COMMENT, REQUESTNO, terminateReason)"+
 		   " VALUES (?,?,?,?,?,?,?,?,?,?)";


tw.local.sqlParameters = new tw.object.listOf.SQLParameter();

tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.startTime));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.endTime));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.userName));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.role));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.step));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.action));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.returnReason));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.comment));
 
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.requestNo));
tw.local.sqlParameters.insertIntoList(tw.local.sqlParameters.listLength, addSQLParameter(tw.local.stepLog.terminateReason));

